INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (197, NULL, 5, NULL, 'EN', 1, 'clinical', 'intrinsic', 'eutils.ncbi.nlm.nih.gov PubMed: wheelchair AND (turning space OR turning radius OR maneuvering space) AND (dimensions OR anthropometry OR clearance)', NULL, 'pubmed', 'scoping', NULL, 4, 4, 0, 'partial', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 02:49', 'Four hits, three on topic: Koontz 2010 (PMID 20434614, T1 case series, n=223, minimum passageway widths for L-turn, 360-degree turn and U-turn); Steinfeld 2010 (PMID 20402047, international comparison of anthropometry and standards); King 2011 (PMID 21657823, scooter three-point-turn areas). One off topic (PMID 36038463, a Delphi study of the word wheelchair-bound). None admitted: Europe PMC reports no open full text for Koontz or Steinfeld (isOpenAccess N, inPMC N), and the abstracts state no dimension, so an admission would add no extractable figure. Koontz and King DOIs are held as RETIRED stash rows (REF-00784, REF-00972): a re-admission cross-files to those ids. Query shape: well-formed; PubMed parsed turning space as turning AND space. Count 4 is below the prior floor of 5; the shortfall reads as an indexing fact (the main US report is not in PubMed), not a query-shape failure.', 0, 'Stated in the session transcript before the search ran: 5-25 hits; at most 1-2 usable measurement studies; the US anthropometry report (Steinfeld et al. 2010) may not be indexed in PubMed; full text unlikely.', 'planned', NULL, NULL, '2026-11-06 02:49', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
INSERT INTO "search_executions" ("exec_id", "slug", "parameter_id", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation", "origin", "mined_ref_id", "origin_pass_id", "updated_at", "updated_by_session", "identity_code", "icf_code", "needs_code", "medical_code") VALUES (198, NULL, 9, NULL, 'EN', 1, 'co1', 'intrinsic', 'eutils.ncbi.nlm.nih.gov PubMed: (wheelchair OR "people with disabilities") AND (doorway OR "door width" OR "corridor width") AND (participatory OR "focus group" OR "lived experience")', NULL, 'pubmed', 'scoping', NULL, 1, 1, 0, 'none', NULL, NULL, 0, 'session_2026-11-06-pipeline-batch', '2026-11-06 02:49', 'ZERO-YIELD for Co-1: the one hit (PMID 18002971, Cooper et al. 2007, robotics for personal mobility) reports focus-group participants naming doorways as a barrier but is an engineering overview, not a participatory dimension study; not a Co-1 source for a door or corridor width and not admitted. R14 diagnosis: QUERY-SHAPE FAILURE, not genuine absence. Three AND-ed concept groups; PubMed does not index participatory design-standard work from disabled persons organisations, which publishes as grey reports. A Co-1 retrieval for door and corridor widths is NOT done by this batch and stays open.', 0, 'Stated in the session transcript before the search ran: 0-3 hits, none qualifying as Co-1; if empty, the likelier cause is three AND-ed concept groups rather than genuine absence.', 'planned', NULL, NULL, '2026-11-06 02:49', 'session_2026-11-06-pipeline-batch', NULL, NULL, NULL, NULL);
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (6, 'REF-00992', 'catalogue', 12, NULL, 'full', 74, 74, '6599e260283e450ef734927c308171e73904d0952664c3f9f2cfdfe2c48e3bbf', 0, 'pre-screen', 'Derived text of all 74 pages (retrieval-log/session_2026-10-30-rest-landing-parameter, 0e5d4dee25b341f4-full-text.txt). NOT read end to end: pages were located by keyword search (corridor, clear width, opening force, light reflectance, headroom, turning, 1500 mm) and pages 16, 17, 22, 27, 32, 33, 34, 35 read in full. Diagrams are images and were not read, so any figure carried only by a diagram (door manoeuvring space, the wheelchair turning space in the sanitary-accommodation guidance) is unread. Parameter 4 (3.14b), 6 (2.13a, 3.10a), 8 (0.26 contrast visually), 9 (Table 2) extracted. Parameters 5, 7, 10, 11: no value found in the text; headroom (1.38-1.39) is referred to Approved Document K, which this file does not hold.', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch');
INSERT INTO "source_scans" ("scan_id", "ref_id", "mode", "catalogue_version", "target_parameter_id", "text_scope", "pages_read", "pages_total", "file_sha256", "open_pass_done", "method", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (7, 'REF-00987', 'catalogue', 12, NULL, 'full', NULL, NULL, 'a2f0dc7adef43a4ace25e5f2792b7ab83a828e56d101f2ed84cbd40c77727554', 0, 'pre-screen', 'The ada.gov 2010 Standards page as retrieved (HTML, text derived by stripping tags; 477 thousand characters). NOT read end to end: sections located by clause number and keyword (403.5.1, 304.3.1, 307.4, 404.2.3, 404.2.9, 309.4, light reflectance, LRV, contrast). Parameters 4 (403.5.1), 5 (304.3.1), 6 (404.2.9), 9 (404.2.3), 11 (307.4) extracted. Parameter 8: no light reflectance value or luminance difference found; the only contrast provisions located are advisory 504.4 (stair nosings) and 703.5.1 (sign characters), neither for a door or surface pair. Parameters 7 and 10: no search hit for reverberation or colour temperature was run; not examined. Figures in the page are images and unread.', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (168, 'REF-00992', NULL, 4, 'MOB', NULL, NULL, NULL, 'UK', 'corridors and passageways, buildings other than dwellings', 'numerical', '1200', 'mm', 'they have an unobstructed width (excluding any projections into the space) along their length of at least 1200mm;', 'Approved Document M Volume 2, para 3.14(b)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', NULL, '3.14', 'b', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 33 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: minimum unobstructed width of a corridor or passageway, excluding projections. Para 3.14(c) adds passing places 1800 mm long and 1800 mm wide where the width is under 1800 mm; that threshold is not filed as a row. Note to 3.14(b): for school buildings the preferred width is 2700 mm where lockers stand in the corridor. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: para 3.11 names wheelchair users passing and turning as the reason for the width].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
