INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (177, 'REF-00992', NULL, 6, 'MOB', NULL, NULL, NULL, 'UK', 'internal doors opened manually, 0 to 30 degrees', 'numerical', '30', 'N', 'the opening force at the leading edge of the door is not more than 30N from 0° (the door in the closed position) to 30° open, and not more than 22.5N from 30° to 60° of the opening cycle;', 'Approved Document M Volume 2, para 3.10(a)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', NULL, '3.10', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 32 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: maximum opening force at the leading edge of an internal door, 0 to 30 degrees open. The same two figures are stated for entrance doors at para 2.13(a), in a conditional form (a powered system is required where the door cannot otherwise be opened within them); not filed twice (rule 5). Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: para 2.9 names wheelchair users and people with limited strength as those a heavy door excludes].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (178, 'REF-00992', NULL, 6, 'MOB', NULL, NULL, NULL, 'UK', 'internal doors opened manually, 30 to 60 degrees', 'numerical', '22.5', 'N', 'the opening force at the leading edge of the door is not more than 30N from 0° (the door in the closed position) to 30° open, and not more than 22.5N from 30° to 60° of the opening cycle;', 'Approved Document M Volume 2, para 3.10(a)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', NULL, '3.10', 'a', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 32 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: maximum opening force at the leading edge of an internal door, 30 to 60 degrees of the opening cycle. See the 0 to 30 degree row for the entrance-door repeat at para 2.13(a). Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: para 2.9].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (179, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'two adjoining surfaces; default case', 'numerical', '30', 'points', 'in light reflectance value between the two surfaces is greater than 30 points.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: difference in light reflectance value (LRV, 0 to 100 scale) between two surfaces for them to count as contrasting visually. The sentence begins on the previous page (PDF page 16 ends "the difference"); the quote starts at the page break. Strictly greater than 30 points. Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: paras 3.8 and 3.12 give people with impaired sight as the reason for visual contrast of doors and walls].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (180, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'two adjoining surfaces; illuminance above 200 lux', 'numerical', '20', 'points', 'Where illuminance on surfaces is greater than 200 lux, a difference in light reflectance value should be a minimum of 20 points.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: reduced LRV difference permitted where illuminance on the surfaces exceeds 200 lux. A relaxation of the 30 point figure, stated as an alternative, not as a condition on a row of another parameter (illuminance is not a parameter here). Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: as the 30 point row].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (181, 'REF-00992', NULL, 8, 'BLIND', NULL, NULL, NULL, 'UK', 'door opening furniture projecting beyond the face of the door', 'numerical', '15', 'points', 'Where door opening furniture projects beyond the face of the door or otherwise creates enhanced differentiation and shade, a minimum difference in light reflectance value of 15 points is considered adequate.', 'Approved Document M Volume 2, para 0.26, definition of contrast visually', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '0', NULL, '0.26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PDF page 17 of 74; 2015 edition incorporating 2020 and 2024 amendments', 'skim', 'preliminary', NULL, 'Quantity: reduced LRV difference considered adequate where door opening furniture projects or otherwise creates differentiation and shade. A relaxation of the 30 point figure. Lens BLIND is the reader''s reading, not the source''s statement [ASSUMPTION: as the 30 point row].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (182, 'REF-00987', NULL, 4, 'MOB', NULL, NULL, NULL, 'US', 'accessible routes', 'numerical', '915', 'mm', 'the clear width of walking surfaces shall be 36 inches (915 mm) minimum.', '2010 ADA Standards for Accessible Design, 403.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', '403.5.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of a walking surface on an accessible route. The source states inches with the millimetre figure beside it; the millimetre figure is the one filed. The exception permits 815 mm for a length of 610 mm maximum, with 1220 mm long, 915 mm wide segments between; not filed as a row. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: chapter 4 is titled accessible routes and the surrounding clauses (403.5.2) set widths for turning around wheelchair-sized elements].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (183, 'REF-00987', NULL, 5, 'MOB', NULL, NULL, NULL, 'US', 'turning space, circular', 'numerical', '1525', 'mm', 'The turning space shall be a space of 60 inches (1525 mm) diameter minimum.', '2010 ADA Standards for Accessible Design, 304.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', '304.3.1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum diameter of the circular turning space. 304.3.2 allows a T-shaped space within a 1525 mm square as the alternative; not filed as a row. Millimetre figure filed as stated beside the inch figure. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: section 304 is titled turning space and is a wheelchair provision].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (184, 'REF-00987', NULL, 6, 'ALL', NULL, NULL, NULL, 'US', 'interior hinged doors and gates', 'numerical', '22.2', 'N', 'Interior hinged doors and gates: 5 pounds (22.2 N) maximum.', '2010 ADA Standards for Accessible Design, 404.2.9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', '404.2.9', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: maximum force to push or pull open an interior hinged door. The same figure is stated for sliding or folding doors in the next line, and for operable parts at 309.4; not filed twice. Fire doors are left to the administrative authority. Lens ALL is the reader''s reading, not the source''s statement [ASSUMPTION: 404.2.9 names no population].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '<=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (185, 'REF-00987', NULL, 9, 'MOB', NULL, NULL, NULL, 'US', 'door openings; clear width', 'numerical', '815', 'mm', 'Door openings shall provide a clear width of 32 inches (815 mm) minimum.', '2010 ADA Standards for Accessible Design, 404.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '4', '404.2.3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum clear width of a door opening, measured between the face of the door and the stop with the door open 90 degrees; 915 mm where the opening is more than 610 mm deep. Lens MOB is the reader''s reading, not the source''s statement [ASSUMPTION: the measurement basis is a swung-open door, the wheelchair-passage case].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (186, 'REF-00987', NULL, 11, 'ALL', NULL, NULL, NULL, 'US', 'protruding objects; walkway vertical clearance', 'numerical', '2030', 'mm', 'Vertical clearance shall be 80 inches (2030 mm) high minimum.', '2010 ADA Standards for Accessible Design, 307.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '3', '307.4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'ada.gov 2010 Standards page, HTML as retrieved 2026-10-30', 'skim', 'preliminary', NULL, 'Quantity: minimum vertical clearance. Door closers and door stops may be 1980 mm minimum (exception, not filed). Guardrails are required where clearance is less. Lens ALL is the reader''s reading, not the source''s statement [ASSUMPTION: 307.4 names no population].', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:51', 'session_2026-11-06-pipeline-batch', 'claim', '>=');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (150, 197, NULL, NULL, 'PENDING-VERIFICATION', 'Koontz et al. 2010, Design features that affect the maneuverability of wheelchairs and scooters (Arch Phys Med Rehabil 91(5):759-64)', 'https://pubmed.ncbi.nlm.nih.gov/20434614/', NULL, 1, 0, NULL, 'HYPOTHESIS from the abstract only (DOI 10.1016/j.apmr.2010.01.009): measured the minimum passageway widths of 223 users (109 manual, 100 power, 14 scooter) for L-turn, 360-degree turn in place and U-turn; reports that 10-100% of users could not manoeuvre in spaces meeting the US guideline. Full text not reached (Europe PMC: subscription only). The DOI is a RETIRED stash row (REF-00784); an admission cross-files to that id. It would anchor parameters 4 and 5 and test the 1525 mm figure against the population measured.', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:50', NULL, 'retrieval-log/session_2026-11-06-pipeline-batch/03b530d696d0a399.json', '20434614', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (151, 197, NULL, NULL, 'PENDING-VERIFICATION', 'Steinfeld, Maisel, Feathers and D Souza 2010, Anthropometry and standards for wheeled mobility: an international comparison (Assist Technol 22(1):51-67)', 'https://pubmed.ncbi.nlm.nih.gov/20402047/', NULL, 2, 0, NULL, 'HYPOTHESIS from the abstract only (DOI 10.1080/10400430903520280): reviews wheeled-mobility anthropometry research from four countries against national standards and reports that US standards, based on 1970s research, need updating. Full text not reached. The DOI sits on two unrelated pre-reset stash rows (REF-00059 and REF-00192: the shuffled-DOI defect, GAP-008), so the cross-filing id is not settled; resolve before any admission.', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:50', NULL, 'retrieval-log/session_2026-11-06-pipeline-batch/03b530d696d0a399.json', '20402047', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch');
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id", "surfaced_in", "surfaced_quote", "updated_at", "updated_by_session") VALUES (152, 197, NULL, NULL, 'PENDING-VERIFICATION', 'King et al. 2011, Design of built environments to accommodate mobility scooter users: part II (Disabil Rehabil Assist Technol 6(5):432-9)', 'https://pubmed.ncbi.nlm.nih.gov/21657823/', NULL, 1, 0, NULL, 'HYPOTHESIS from the abstract only (DOI 10.3109/17483107.2010.549898): measured room areas for a three-point turn for two four-wheeled scooters; states the 1.5 m turning circle is the current standard for manual wheelchairs. Full text not reached. Scooter users, so a PROXY for the population the 1525 mm figure serves. The DOI is a RETIRED stash row (REF-00972).', 'session_2026-11-06-pipeline-batch', '2026-11-06 02:50', NULL, 'retrieval-log/session_2026-11-06-pipeline-batch/03b530d696d0a399.json', '21657823', '2026-11-06 02:50', 'session_2026-11-06-pipeline-batch');
